function companyPage(){return `${policyPageHeader('About Us','A Kuching-based general contractor delivering building and civil engineering work since 2003.','company-background','top')}<section class="company-story shell" id="company-story"><div class="company-story-copy"><span class="section-tag">OUR WORK / OUR PEOPLE</span><h2>From the ground up.<br><span>Across Malaysia.</span></h2><p>Today, the company undertakes major building and civil engineering works across commercial and government buildings, roads, highways, bridges, schools, water pipelines, slope repair and maintenance.</p><p>Its people bring management and technical experience to each project, supported by a substantial fleet of construction machinery.</p></div><figure class="company-story-image"><img src="assets/source-630.jpg" alt="Belianemas Synergy staff at a team event" loading="lazy"><figcaption><span>THE PEOPLE BEHIND THE WORK</span><span>KUCHING, SARAWAK</span></figcaption></figure></section><section class="company-operating"><div class="shell company-operating-inner"><div class="company-operating-heading"><span class="section-tag">THE CAPACITY BEHIND DELIVERY</span><h2>People, experience<br>and the right plant.</h2><p>The company profile records a fleet of 94 units of heavy machinery, backed by professional management and technical experience.</p></div><div class="company-equipment"><strong>94</strong><span>UNITS OF HEAVY MACHINERY</span><p>Construction plant and equipment supporting civil engineering and building works.</p></div></div></section><section class="company-record shell"><div class="company-record-heading"><span class="section-tag">CORPORATE PROFILE</span><h2>A clear record.<br><span>Qualified to deliver.</span></h2></div><dl class="company-record-list"><div><dt>Company</dt><dd>Belianemas Synergy Sdn Bhd</dd></div><div><dt>Established</dt><dd>15 July 2003 · Kuching, Sarawak</dd></div><div><dt>Business</dt><dd>General contractors, property developers and general suppliers</dd></div><div><dt>Contractor registrations</dt><dd>UPKJ Class A · CIDB Grade G7 · 4-star SCORE · PPK · SPKK</dd></div><div><dt>Management system</dt><dd>ISO 9001:2015 for building and civil engineering construction services</dd></div></dl></section>`}
function aboutPage(){return companyPage()}
function policyText(value){return String(value).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function renderPolicy(key){
 const policy=window.BES_POLICY_SOURCE?.[key];
 if(!policy)return '';
 const lines=policy.text.replace(/\r/g,'').split('\n');
 const out=[];let list='',table=false;
 function closeList(){if(list){out.push(`</${list}>`);list=''}}
 function closeTable(){if(table){out.push('</tbody></table></div>');table=false}}
 for(let i=1;i<lines.length;i++){
  const raw=lines[i],line=raw.trim();
  if(!line){closeList();closeTable();continue}
  if(/^APPROVED BY THE BOARD OF DIRECTORS ON 06 JANUARY 2026\.?$/.test(line))continue;
  const section=line.match(/^(\d{1,2})\.\s+([A-Z][A-Z0-9 &,()/'’-]+)$/);
  if(section){closeList();closeTable();out.push(`<h2 id="policy-section-${section[1]}"><span>${section[1].padStart(2,'0')}</span>${policyText(section[2])}</h2>`);continue}
  if(line.includes('|')||table){
   closeList();const cells=line.split('|').map(cell=>cell.trim());
   if(!table){out.push('<div class="policy-table" role="region" aria-label="ABMS objectives table" tabindex="0"><table><thead><tr>'+cells.map(cell=>`<th scope="col">${policyText(cell)}</th>`).join('')+'</tr></thead><tbody>');table=true;continue}
   if(cells.every(cell=>/^-+$/.test(cell)))continue;
   if(cells.length===2)cells.unshift('','');
   while(cells.length<5)cells.push('');
   out.push('<tr>'+cells.map(cell=>`<td>${policyText(cell)}</td>`).join('')+'</tr>');continue
  }
  const bullet=line.match(/^\*\s+(.*)$/),numbered=line.match(/^(\d+)\.\s+(.+)$/);
  if(bullet||numbered){closeTable();const next=bullet?'ul':'ol';if(list!==next){closeList();out.push(`<${next}>`);list=next}out.push(`<li>${policyText(bullet?bullet[1]:numbered[2])}</li>`);continue}
  closeList();
  if(line==='ABMS Objectives Table'){out.push('<h3>ABMS Objectives Table</h3>');continue}
  closeTable();
  let content=policyText(line);
  content=content.replace(/reportfraud@belianemas\.my/g,'<a href="mailto:reportfraud@belianemas.my">reportfraud@belianemas.my</a>');
  content=content.replace(/\(DOWNLOAD HERE\)/g,'<a href="https://www.belianemas.com.my/wp-content/uploads/2026/03/ABMS_17-Whistleblowing-Form.pdf" target="_blank" rel="noopener">(DOWNLOAD HERE)</a>');
  out.push(`<p>${content}</p>`);
 }
 closeList();closeTable();
 const title=key==='antiBribery'?'Anti-Bribery and Corruption (ABC) Policy':'Whistleblowing Procedure';
 const description=key==='antiBribery'?'Our standards for preventing bribery and corruption in every business dealing.':'A clear way for staff, stakeholders and the public to report suspected wrongdoing.';
 return `${policyPageHeader(title,description)}<article class="policy-document shell" aria-label="${title}">${out.join('')}</article>`
}
function antiBriberyPage(){return renderPolicy('antiBribery')}
function whistleblowingPage(){return renderPolicy('whistleblowing')}
