 const track=$('.carousel-track',root), viewport=$('.carousel-window',root), slides=$$('.carousel-slide',track), pause=$('[data-pause]',root), status=$('.carousel-status',root);
 let first=0, busy=false, manualPause=reducedMotion.matches||root.dataset.carousel==='accreditations', hovered=false, focused=false, visible=false, timer, finishTimer, pointerStart=null, dragged=false;
 const count=slides.length, isProjects=root.dataset.carousel==='projects', interval=isProjects?6500:4800;
 function shown(){return Number(getComputedStyle(root).getPropertyValue('--visible-slides'))||3}
 function update(){const order=$$('.carousel-slide',track);order.forEach((s,i)=>{s.inert=i>=shown();s.setAttribute('aria-hidden',String(i>=shown()))});if(status)status.textContent=`${String(first+1).padStart(2,'0')} / ${String(count).padStart(2,'0')}`;if(pause){pause.textContent=manualPause?'▶':'Ⅱ';pause.setAttribute('aria-label',`${manualPause?'Play':'Pause'} ${isProjects?'project':'accreditation'} carousel`);pause.setAttribute('aria-pressed',String(manualPause))}root.classList.toggle('is-paused',manualPause||hovered||focused||!visible||document.hidden||dialog.open)}
 function schedule(){clearTimeout(timer);update();if(!manualPause&&!hovered&&!focused&&visible&&!document.hidden&&!dialog.open)timer=setTimeout(()=>move(1,false),interval)}
 function move(direction,manual=true){if(busy)return;if(manual)manualPause=true;clearTimeout(timer);busy=true;const step=track.firstElementChild.getBoundingClientRect().width+parseFloat(getComputedStyle(track).columnGap||0);const finish=()=>{clearTimeout(finishTimer);track.style.transition='none';if(direction>0)track.append(track.firstElementChild);track.style.transform='translateX(0)';first=(first+direction+count)%count;busy=false;update();schedule()};if(reducedMotion.matches){if(direction<0)track.prepend(track.lastElementChild);finish();return}track.style.transition='none';if(direction<0){track.prepend(track.lastElementChild);track.style.transform=`translateX(-${step}px)`}else track.style.transform='translateX(0)';void track.offsetWidth;track.style.transition='transform 700ms cubic-bezier(.22,.61,.36,1)';track.style.transform=direction>0?`translateX(-${step}px)`:'translateX(0)';finishTimer=setTimeout(finish,720)}
 $('[data-prev]',root).addEventListener('click',()=>move(-1));$('[data-next]',root).addEventListener('click',()=>move(1));if(pause)pause.addEventListener('click',()=>{manualPause=!manualPause;schedule()});
 viewport.addEventListener('keydown',e=>{if(e.key==='ArrowLeft'||e.key==='ArrowRight'){e.preventDefault();move(e.key==='ArrowRight'?1:-1)}});
 root.addEventListener('pointerenter',e=>{if(e.pointerType!=='touch'){hovered=true;schedule()}});root.addEventListener('pointerleave',()=>{hovered=false;schedule()});
