 viewport.addEventListener('pointerdown',e=>{pointerStart={x:e.clientX,y:e.clientY};dragged=false});viewport.addEventListener('pointerup',e=>{if(!pointerStart)return;const dx=e.clientX-pointerStart.x,dy=e.clientY-pointerStart.y;if(Math.abs(dx)>45&&Math.abs(dx)>Math.abs(dy)){dragged=true;move(dx<0?1:-1)}pointerStart=null});viewport.addEventListener('pointercancel',()=>pointerStart=null);viewport.addEventListener('click',e=>{if(dragged){e.preventDefault();e.stopPropagation();dragged=false}},true);
 new IntersectionObserver(entries=>{visible=entries[0].isIntersecting;schedule()},{threshold:.2}).observe(root);
