if(!reducedMotion.matches&&'IntersectionObserver' in window){const revealObserver=new IntersectionObserver(entries=>entries.forEach(entry=>{if(entry.isIntersecting){entry.target.classList.add('is-visible');revealObserver.unobserve(entry.target)}}),{threshold:.12});$$('.project-carousel .carousel-slide,.capability-spotlight,.capability-option').forEach((el,i)=>{el.classList.add('cinematic-reveal');el.style.setProperty('--reveal-delay',`${(i%5)*80}ms`);revealObserver.observe(el)})}
